/**
 * Footprint resolution.
 *
 * A footprint is the single most expensive thing to get wrong in this domain: an
 * incorrect land pattern is a board that has to be thrown away. So every resolved
 * footprint records *how* it was resolved and whether the result is trustworthy, and
 * nothing is silently marked verified.
 *
 * Resolution order:
 *   1. `footprinterString`  — generated by @tscircuit/footprinter, verified
 *   2. `circuitJsonElements` — supplied by the part definition, trusted as given
 *   3. `kicadModRef`        — resolved at M8 via kicad-mod-converter
 *   4. nothing              — unverified, and the caller is told why
 */

import { fp } from "@tscircuit/footprinter"
import type { Result, ValidationError } from "@syntrix/shared"
import { err, newElementId, ok, validationError } from "@syntrix/shared"
import type { Footprint } from "./types"

export interface ResolvedFootprint {
  /** pcb_* circuit-json elements, with ids filled in. */
  elements: unknown[]
  /** How many pads or plated holes the footprint has. */
  padCount: number
  /** Pad `port_hints` in pad order — how a pad maps back to a pin number. */
  padHints: string[][]
  verification: "verified" | "unverified"
  /** Which branch resolved it, for provenance and debugging. */
  resolvedBy: "footprinter" | "circuit_json" | "kicad_mod" | "none"
  source?: string
}

const PAD_TYPES = new Set(["pcb_smtpad", "pcb_plated_hole", "pcb_hole"])

const isPad = (element: unknown): boolean =>
  PAD_TYPES.has((element as { type?: string })?.type ?? "")

/**
 * Footprinter emits elements with empty id fields. Filling them here keeps ids
 * consistent with the rest of the document and lets the deterministic id factory make
 * footprint output reproducible in tests.
 */
const assignIds = (elements: unknown[]): unknown[] =>
  elements.map((element) => {
    const record = { ...(element as Record<string, unknown>) }
    const type = record["type"]
    if (typeof type !== "string") return record

    const idKey = `${type}_id`
    if (record[idKey] === "" || record[idKey] === undefined) {
      record[idKey] = newElementId(type)
    }
    return record
  })

/**
 * Resolve a footprint specification into pcb elements.
 *
 * Never throws: an unresolvable footprint is a normal outcome that the parts UI shows as
 * "unverified", and the agent's house rules steer away from.
 */
export const resolveFootprint = (
  footprint: Footprint,
): Result<ResolvedFootprint, ValidationError[]> => {
  if (footprint.footprinterString) {
    try {
      const elements = assignIds(fp.string(footprint.footprinterString).circuitJson())
      const pads = elements.filter(isPad)

      if (pads.length === 0) {
        return err([
          validationError(
            "FOOTPRINT_UNRESOLVED",
            `Footprinter produced no pads for "${footprint.footprinterString}".`,
            "Check the footprinter string — a package name alone is often not enough (for example 'soic' needs a pin count, as in 'soic8').",
            [],
            { footprinterString: footprint.footprinterString },
          ),
        ])
      }

      return ok({
        elements,
        padCount: pads.length,
        padHints: pads.map((p) => (p as { port_hints?: string[] }).port_hints ?? []),
        // Footprinter generates land patterns from IPC-derived rules, so its output is
        // the one source we treat as verified without a human check.
        verification: "verified",
        resolvedBy: "footprinter",
        source: footprint.footprinterString,
      })
    } catch (cause) {
      return err([
        validationError(
          "FOOTPRINT_UNRESOLVED",
          `Footprinter could not parse "${footprint.footprinterString}": ${
            cause instanceof Error ? cause.message : String(cause)
          }`,
          "Use a supported footprinter string such as '0603', 'sot223', 'soic8' or 'qfn32'. Run getFootprintNames() to list them.",
          [],
          { footprinterString: footprint.footprinterString },
        ),
      ])
    }
  }

  if (footprint.circuitJsonElements && footprint.circuitJsonElements.length > 0) {
    const elements = assignIds(footprint.circuitJsonElements)
    const pads = elements.filter(isPad)
    return ok({
      elements,
      padCount: pads.length,
      padHints: pads.map((p) => (p as { port_hints?: string[] }).port_hints ?? []),
      // Trusted exactly as far as the part definition claims — pre-supplied geometry is
      // only as good as whoever supplied it.
      verification: footprint.verification,
      resolvedBy: "circuit_json",
    })
  }

  if (footprint.kicadModRef) {
    return err([
      validationError(
        "FOOTPRINT_UNRESOLVED",
        `KiCad footprint "${footprint.kicadModRef}" cannot be resolved yet.`,
        "KiCad library import lands at M8. Until then, give the part a footprinterString or pre-resolved pcb elements.",
        [],
        { kicadModRef: footprint.kicadModRef },
      ),
    ])
  }

  return err([
    validationError(
      "FOOTPRINT_UNRESOLVED",
      "The part has no footprint information.",
      "Add a footprinterString (for example '0603' or 'sot223'), a kicadModRef, or pre-resolved pcb elements to the part definition.",
    ),
  ])
}

/**
 * Check that a footprint's pads line up with the part's pins.
 *
 * A 3-pin part on an 8-pad footprint is a mistake that reaches the board house if nobody
 * looks, so this runs whenever a part is added to the catalog.
 */
export const verifyPinMapping = (
  resolved: ResolvedFootprint,
  pinNumbers: Array<number | string>,
): Result<true, ValidationError[]> => {
  if (resolved.padCount !== pinNumbers.length) {
    return err([
      validationError(
        "PIN_MAP_INCOMPLETE",
        `The part has ${pinNumbers.length} pin(s) but its footprint has ${resolved.padCount} pad(s).`,
        "Either the pin list or the footprint is wrong for this package. Check the datasheet's pin count against the package name.",
        [],
        { padCount: resolved.padCount, pinCount: pinNumbers.length },
      ),
    ])
  }

  // Every pin must be reachable from some pad's hints, or routing cannot attach a net to
  // it even though the pad exists.
  const hinted = new Set(resolved.padHints.flat().map((h) => h.toLowerCase()))
  const unmapped = pinNumbers.filter((pin) => !hinted.has(String(pin).toLowerCase()))

  if (unmapped.length > 0) {
    return err([
      validationError(
        "PIN_MAP_INCOMPLETE",
        `Pin(s) ${unmapped.join(", ")} do not correspond to any pad on the footprint.`,
        "The footprint's pads are labelled by number in their port_hints. Check that the part's pin numbers match the package's pad numbering.",
        [],
        { unmapped },
      ),
    ])
  }

  return ok(true)
}

/** The footprinter strings this project has verified pad counts for. */
export const KNOWN_FOOTPRINTS: Record<string, number> = {
  "0201": 2,
  "0402": 2,
  "0603": 2,
  "0805": 2,
  "1206": 2,
  sot23: 3,
  sot23_3: 3,
  sot223: 4,
  soic8: 8,
  soic14: 14,
  soic16: 16,
  tssop8: 8,
  tssop16: 16,
  qfn32: 32,
  tqfp32: 32,
  lqfp48: 48,
  to220: 3,
  dip8: 8,
  dip16: 16,
}
